/* Ders 37 — Jeneratör ve ATS */
ELK_DERS[37] = {
hafta: 8,
baslik: "Jeneratör ve ATS",
hedef: [
  "Jeneratörün kVA ve kW değerlerini yük listesiyle karşılaştırıp yetip yetmeyeceğini hesaplayabilirsin.",
  "ATS'nin çalışma sırasını ve iki kaynağın neden asla birleşmemesi gerektiğini anlatabilirsin.",
  "Jeneratörlü tesiste nötr, topraklama ve faz sırası kaynaklı arızaları tanıyabilirsin."
],
saha: `Bir otelde elektrik kesiliyor, jeneratör 10 saniyede devreye giriyor. Işıklar yanıyor, ama mutfaktaki bazı kaçak akım röleleri atıyor ve havalandırma fanlarından biri ters dönüyor. Şebeke gelince her şey düzeliyor. Jeneratörcü "makinede sorun yok" diyor, gerçekten de çıkış gerilimi ve frekansı tam. Peki sorun nerede ve neden sadece jeneratördeyken ortaya çıkıyor?`,
parcalar: [
  { baslik: "kVA ve kW: iki ayrı sınır",
    metin: `Jeneratör iki makinedir: mili döndüren <b>dizel motor</b> ve elektriği üreten <b>alternatör</b>. Dizel motor yalnız aktif gücü (kW) karşılar, çünkü iş yapan güç budur. Alternatörü ise sargılarından geçen akım ısıtır, yani görünür güç (kVA) sınırlar (Ders 8).<br><br>Etiketteki kVA değeri <b>cosφ = 0,8</b> esas alınarak verilir: <b>P = S × 0,8</b>. 400 kVA'lık jeneratör en fazla 320 kW verir. Buradan iki ayrı sınır çıkar:<br>• Yükün cosφ'si 0,8'in <b>altındaysa</b> önce alternatör akımı (kVA) dolar.<br>• Yükün cosφ'si 0,8'in <b>üstündeyse</b> önce dizel motorun gücü (kW) dolar.<br><br>Sahada en sık atlanan ikincisidir. 250 kVA'lık jeneratöre 220 kW, cosφ = 0,95 yük bağlandı diyelim. Görünür güç 220 / 0,95 ≈ 232 kVA, 250'nin altında; "yeter" gibi görünür. Ama motor en fazla 250 × 0,8 = 200 kW verir. 220 kW'ta motor zorlanır, devir ve frekans düşer, kara duman atar.<br><br>Kural: yük listesinden <b>hem toplam kW'ı hem toplam kVA'yı</b> hesapla; jeneratörün kW'ı da kVA'sı da ikisinden büyük olsun. Üstüne büyük motorların kalkışı ve gelecekteki ek yük için pay bırak.`,
    sema: "",
    akilda: "Jeneratörün kVA'sını alternatör, kW'ını (kVA × 0,8) dizel motor sınırlar; yükün hem kW'ı hem kVA'sı ayrı ayrı kontrol edilir." },
  { baslik: "ATS: kim, ne zaman, hangi sırayla",
    metin: `ATS (otomatik transfer şalteri) şebekeyi izleyen ve yükü iki kaynak arasında taşıyan bir enversördür. Mantığı Ders 34'teki ileri-geri devresinin aynısıdır: iki kontaktör veya iki motorlu şalter, araya <b>elektriksel ve mekanik kilit</b>. Orada iki kontaktörün birlikte kapanması faz-faz kısa devre demekti. Burada iki kaynağın birlikte bağlanması, senkron olmayan iki gerilimin birbirine bağlanması demektir; sonuç patlayan şalter ve hasarlı alternatördür.<br><br>Sıra şemadaki gibidir. Şebeke gidince ATS önce kısa bir <b>onay gecikmesi</b> bekler; anlık gerilim çukuru için jeneratör boşuna çalışmasın. Sonra start verir, gerilim ve frekans oturunca yükü aktarır. Şebeke dönünce hemen geri geçmez; <b>geri dönüş gecikmesi</b> şebekenin kararlı olduğundan emin olmak içindir. Yük şebekeye geçtikten sonra jeneratör bir süre yüksüz <b>soğuma</b> çalışması yapar ve durur.<br><br>Bir tehlike daha var: kilitsiz veya elle yapılmış bir transferde jeneratör şebekeye <b>geri besleme</b> yapabilir. Trafo bu kez yükseltici olarak çalışır ve hattı "kesik" sanıp çalışan ekip enerjiyle karşılaşır. Beş altın kuralın (Ders 12) "her yönden ayır" maddesi jeneratörlü tesiste bu yüzden vardır.`,
    sema: `<svg viewBox="0 0 460 230"><rect width="460" height="230" fill="#ffffff"/><rect x="10" y="30" width="100" height="44" fill="none" stroke="#b91c1c" stroke-width="1.5"/><text x="60" y="48" fill="#1c232d" font-size="10" text-anchor="middle">1) Şebeke</text><text x="60" y="63" fill="#1c232d" font-size="10" text-anchor="middle">kesildi</text><rect x="123" y="30" width="100" height="44" fill="none" stroke="#b45309" stroke-width="1.5"/><text x="173" y="48" fill="#1c232d" font-size="10" text-anchor="middle">2) Onay gecikmesi</text><text x="173" y="63" fill="#1c232d" font-size="10" text-anchor="middle">(birkaç saniye)</text><rect x="236" y="30" width="100" height="44" fill="none" stroke="#b45309" stroke-width="1.5"/><text x="286" y="48" fill="#1c232d" font-size="10" text-anchor="middle">3) Marş, ısınma</text><text x="286" y="63" fill="#1c232d" font-size="10" text-anchor="middle">V ve f oturur</text><rect x="349" y="30" width="100" height="44" fill="none" stroke="#15803d" stroke-width="1.5"/><text x="399" y="48" fill="#1c232d" font-size="10" text-anchor="middle">4) Yük jeneratöre</text><text x="399" y="63" fill="#1c232d" font-size="10" text-anchor="middle">aktarılır</text><line x1="110" y1="52" x2="123" y2="52" stroke="#4b5563" stroke-width="1.5"/><line x1="223" y1="52" x2="236" y2="52" stroke="#4b5563" stroke-width="1.5"/><line x1="336" y1="52" x2="349" y2="52" stroke="#4b5563" stroke-width="1.5"/><line x1="399" y1="74" x2="399" y2="102" stroke="#4b5563" stroke-width="1.5"/><line x1="399" y1="102" x2="60" y2="102" stroke="#4b5563" stroke-width="1.5"/><line x1="60" y1="102" x2="60" y2="120" stroke="#4b5563" stroke-width="1.5"/><text x="230" y="95" fill="#4b5563" font-size="10" text-anchor="middle">şebeke dönene kadar yükü jeneratör taşır</text><rect x="10" y="120" width="100" height="44" fill="none" stroke="#0369a1" stroke-width="1.5"/><text x="60" y="138" fill="#1c232d" font-size="10" text-anchor="middle">5) Şebeke</text><text x="60" y="153" fill="#1c232d" font-size="10" text-anchor="middle">geri geldi</text><rect x="123" y="120" width="100" height="44" fill="none" stroke="#0369a1" stroke-width="1.5"/><text x="173" y="138" fill="#1c232d" font-size="10" text-anchor="middle">6) Geri dönüş</text><text x="173" y="153" fill="#1c232d" font-size="10" text-anchor="middle">gecikmesi (dk)</text><rect x="236" y="120" width="100" height="44" fill="none" stroke="#0369a1" stroke-width="1.5"/><text x="286" y="138" fill="#1c232d" font-size="10" text-anchor="middle">7) Yük şebekeye</text><text x="286" y="153" fill="#1c232d" font-size="10" text-anchor="middle">geri aktarılır</text><rect x="349" y="120" width="100" height="44" fill="none" stroke="#4b5563" stroke-width="1.5"/><text x="399" y="138" fill="#1c232d" font-size="10" text-anchor="middle">8) Soğuma</text><text x="399" y="153" fill="#1c232d" font-size="10" text-anchor="middle">çalışması, stop</text><line x1="110" y1="142" x2="123" y2="142" stroke="#4b5563" stroke-width="1.5"/><line x1="223" y1="142" x2="236" y2="142" stroke="#4b5563" stroke-width="1.5"/><line x1="336" y1="142" x2="349" y2="142" stroke="#4b5563" stroke-width="1.5"/><text x="10" y="186" fill="#b91c1c" font-size="10">Kilitleme: şebeke ve jeneratör kontaktörü ASLA aynı anda kapalı olamaz</text><text x="10" y="201" fill="#4b5563" font-size="10">(mekanik + elektriksel kilit). Geçişte birkaç saniyelik kesinti olur;</text><text x="10" y="216" fill="#4b5563" font-size="10">kesintisiz beslenmesi gereken yükler için ayrıca UPS kullanılır.</text></svg>`,
    akilda: "ATS bir enversördür: iki kaynak asla aynı anda bağlanmaz; onay, aktarma, geri dönüş ve soğuma bu sırayla olur." },
  { baslik: "Nötr ve topraklama: 3 kutup mu, 4 kutup mu",
    metin: `İki kaynaklı tesiste nötrün nerede topraklandığı belirleyicidir. Trafonun yıldız noktası trafo merkezinde topraklanmıştır (Ders 36). Jeneratörün alternatörü de yıldız bağlıdır ve onun nötrü de çoğu zaman kendi gövdesinde PE'ye bağlanır.<br><br>ATS yalnız üç fazı anahtarlıyorsa (<b>3 kutuplu</b>) nötr iki kaynakta ortak kalır ve iki ayrı N-PE bağı arasında bir döngü oluşur. Bina nötrünün akımının bir kısmı nötr yerine PE üzerinden döner. Bunun iki sonucu var: PE iletkeni ve metal gövdeler yük akımı taşır, ve kaçak akım röleleri toroidin içinden geçmeyen bir dönüş yolu gördüğü için <b>hatalı açar</b> (Ders 22).<br><br>Çözüm projede baştan belirlenir. Ya <b>4 kutuplu ATS</b> kullanılır ve nötr de fazlarla birlikte anahtarlanır, böylece hangi kaynak bağlıysa yalnız onun N-PE bağı devrededir. Ya da 3 kutuplu ATS ile tek bir ortak N-PE noktası kurulur ve jeneratördeki bağ kaldırılır. İki çözümü karıştırmak, yani 3 kutuplu ATS ile jeneratörde N-PE bağını bırakmak, sahadaki klasik hatadır. PE hiçbir koşulda anahtarlanmaz.`,
    sema: `<svg viewBox="0 0 460 260"><rect width="460" height="260" fill="#ffffff"/><rect x="20" y="30" width="90" height="50" fill="none" stroke="#4b5563" stroke-width="1.5"/><text x="65" y="52" fill="#1c232d" font-size="11" text-anchor="middle">Şebeke</text><text x="65" y="68" fill="#4b5563" font-size="10" text-anchor="middle">(trafo)</text><rect x="20" y="120" width="90" height="50" fill="none" stroke="#4b5563" stroke-width="1.5"/><text x="65" y="142" fill="#1c232d" font-size="11" text-anchor="middle">Jeneratör</text><text x="65" y="158" fill="#4b5563" font-size="10" text-anchor="middle">(G)</text><line x1="110" y1="45" x2="200" y2="45" stroke="#b45309" stroke-width="3"/><line x1="110" y1="65" x2="200" y2="65" stroke="#0369a1" stroke-width="2"/><line x1="110" y1="135" x2="200" y2="135" stroke="#b45309" stroke-width="3"/><line x1="110" y1="155" x2="200" y2="155" stroke="#0369a1" stroke-width="2"/><text x="155" y="40" fill="#b45309" font-size="9.5" text-anchor="middle">L1-L2-L3</text><text x="155" y="78" fill="#0369a1" font-size="9.5" text-anchor="middle">N</text><text x="155" y="130" fill="#b45309" font-size="9.5" text-anchor="middle">L1-L2-L3</text><text x="155" y="168" fill="#0369a1" font-size="9.5" text-anchor="middle">N</text><rect x="200" y="30" width="90" height="140" fill="none" stroke="#6d28d9" stroke-width="2"/><text x="245" y="92" fill="#6d28d9" font-size="10" text-anchor="middle">4 kutuplu ATS</text><text x="245" y="108" fill="#1c232d" font-size="10" text-anchor="middle">L1-L2-L3 + N</text><text x="245" y="124" fill="#1c232d" font-size="10" text-anchor="middle">birlikte geçer</text><line x1="290" y1="95" x2="360" y2="95" stroke="#b45309" stroke-width="3"/><line x1="290" y1="118" x2="360" y2="118" stroke="#0369a1" stroke-width="2"/><rect x="360" y="80" width="85" height="55" fill="none" stroke="#4b5563" stroke-width="1.5"/><text x="402" y="104" fill="#1c232d" font-size="11" text-anchor="middle">Yük</text><text x="402" y="120" fill="#4b5563" font-size="10" text-anchor="middle">(TN-S)</text><line x1="10" y1="215" x2="445" y2="215" stroke="#15803d" stroke-width="3"/><line x1="14" y1="55" x2="14" y2="215" stroke="#15803d" stroke-width="1.5" stroke-dasharray="4 3"/><line x1="14" y1="55" x2="20" y2="55" stroke="#15803d" stroke-width="1.5"/><line x1="65" y1="170" x2="65" y2="215" stroke="#15803d" stroke-width="1.5" stroke-dasharray="4 3"/><line x1="402" y1="135" x2="402" y2="215" stroke="#15803d" stroke-width="1.5"/><text x="75" y="200" fill="#15803d" font-size="10">N-PE bağları (iki kaynakta ayrı)</text><text x="245" y="190" fill="#15803d" font-size="10" text-anchor="middle">PE anahtarlanmaz</text><text x="300" y="208" fill="#15803d" font-size="10">PE / ana toprak barası</text><text x="10" y="236" fill="#4b5563" font-size="9.5">Jeneratörde de N-PE bağı varsa N de kesilmelidir; aksi halde nötr akımı PE</text><text x="10" y="251" fill="#4b5563" font-size="9.5">üzerinden paralel yol bulur ve kaçak akım röleleri hatalı açar.</text></svg>`,
    akilda: "N-PE bağı her kaynakta varsa nötr de anahtarlanmalı (4 kutup); aksi hâlde nötr akımı PE'den döner ve kaçak akım röleleri atar." },
  { baslik: "Devreye alma ve test: üç kontrol",
    metin: `<b>1) Faz sırası.</b> ATS'nin iki girişinde faz sırası ölçerle bak. Jeneratör kabloları L1 ile L3 ters bağlanmışsa her şey çalışır görünür, ama jeneratöre geçince bütün üç fazlı motorlar ters döner (Ders 34). Pompa basınç yapmaz, fan ters üfler, asansör yanlış yöne kalkar. Düzeltme jeneratör çıkışında iki fazı değiştirerek yapılır, motorlarda değil.<br><br><b>2) Kısa devre akımı.</b> Şebekede ADP'de onlarca kA olabilir (Ders 36). Jeneratörde sürekli kısa devre akımı ise anma akımının yalnız birkaç katıdır. Şebekede manyetik açıcıyla anında açan bir otomatik sigorta, jeneratör beslemesinde termik bölgede kalıp geç açabilir. Bu yüzden jeneratörlü tesiste koruma ayarları ve döngü empedansı jeneratör beslemesi için de kontrol edilir (Ders 15, 18).<br><br><b>3) Yüklü test.</b> Jeneratör yalnız boşta çalıştırılırsa sorunların yarısı görünmez. Belirli aralıklarla şebekeyi ATS üzerinden keserek gerçek yükle test edilir: transfer süresi, gerilim ve frekans, yük altında akımlar, geri dönüş. Büyük motorların kalkışında gerilim çukuru belirginse o motorlara yumuşak yol verici veya sürücü düşünülür (Ders 35), ya da kalkışlar sıraya konur.`,
    sema: "",
    akilda: "Jeneratöre geçince faz sırası aynı olmalı, korumalar küçük kısa devre akımında da açmalı ve test gerçek yükle yapılmalı." }
],
ornek: {
  baslik: "Bir fabrikanın acil yükleri için jeneratör",
  adimlar: [
    "Yük listesi: aydınlatma 20 kW, cosφ 0,95; motorlar (pompa, fan) 60 kW, cosφ 0,8; UPS 30 kW, cosφ 0,9.",
    "Reaktif güçler Q = P × tanφ: aydınlatma 20 × 0,33 ≈ 6,6 kVAr; motorlar 60 × 0,75 = 45 kVAr; UPS 30 × 0,48 ≈ 14,5 kVAr.",
    "Toplam: P = 110 kW, Q ≈ 66 kVAr. Görünür güç S = √(110² + 66²) ≈ 128 kVA. Ortalama cosφ = 110 / 128 ≈ 0,86.",
    "cosφ 0,8'in üstünde olduğu için sınır dizel motordur: gereken jeneratör en az 110 / 0,8 ≈ 138 kVA. Sadece kVA'ya bakan 128 kVA'ya yeter sanırdı.",
    "En büyük motorun kalkışı ve ileride eklenecek yük için yaklaşık %25 pay: 138 × 1,25 ≈ 172 kVA. Bir üst standart güç seçilir, örneğin 200 kVA.",
    "Kontrol: 200 kVA jeneratör 160 kW verir (110 kW'ın üstünde), AG anma akımı 200 000 / (1,732 × 400) ≈ 289 A. ATS ve çıkış kesicisi bu akıma göre seçilir."
  ],
  sonuc: "Jeneratör boyutunu yükün kVA'sı değil, kW / 0,8 ile kVA'nın büyüğü belirler. Üstüne kalkış ve büyüme payı eklenir; ATS ve kablolar jeneratörün anma akımına göre seçilir."
},
yokla: [
  { s: "Hesapla: 500 kVA'lık jeneratör en fazla kaç kW verir? cosφ 0,7 olan bir yükte hangi sınır önce dolar?", c: "500 × 0,8 = 400 kW. cosφ 0,8'in altında olduğu için önce alternatör akımı (kVA) dolar: 500 kVA'da yük yalnız 350 kW olur." },
  { s: "Şebeke dönünce ATS neden hemen geri geçmez?", c: "Şebeke dönüşte kısa süre gidip gelebilir; hemen geçerse yük iki kez kesilebilir. Geri dönüş gecikmesi şebekenin kararlı olduğundan emin olmak içindir." },
  { s: "3 kutuplu ATS'li bir binada jeneratördeyken kaçak akım röleleri atıyor, şebekedeyken atmıyor. İlk şüphen ne?", c: "Jeneratörde de N-PE bağı var ve nötr anahtarlanmıyor; nötr akımı PE üzerinden paralel yol buluyor. Proje 4 kutuplu ATS veya tek N-PE noktası ister." },
  { s: "Jeneratöre geçince bütün fanlar ters dönüyor. Neyi kontrol eder, düzeltmeyi nerede yaparsın?", c: "ATS'nin iki girişinde faz sırasını. Jeneratör tarafında iki fazın yeri değiştirilir; motorlarda değişiklik yapılmaz, yoksa şebekede ters dönerler." },
  { s: "(Ders 34) ATS'deki kilitleme hangi ders konusuyla aynı mantığa dayanır, iki kontaktör birlikte kapanırsa ne olur?", c: "Enversör kilidiyle aynıdır: elektriksel ve mekanik kilit. ATS'de iki kaynak birlikte bağlanırsa senkron olmayan iki gerilim birleşir; şalter ve alternatör ağır hasar görür." },
  { s: "(Ders 22) Nötr akımı PE üzerinden dönünce kaçak akım rölesi neden atar?", c: "Röle toroidden geçen faz ve nötr akımlarının toplamına bakar. Dönüş akımının bir kısmı toroidin dışından, PE'den gidince fark oluşur ve röle bunu kaçak sayar." }
],
sahada: [
  "Çalıştığın binada jeneratörün etiketindeki kVA, kW ve cosφ değerlerini oku; ATS'nin 3 kutuplu mu 4 kutuplu mu olduğuna bak.",
  "Jeneratör gövdesinde veya alternatör klemens kutusunda N-PE bağı olup olmadığını projeyle karşılaştır; enerjili kısımlara yetkisiz dokunma.",
  "Planlı bir yüklü test varsa transfer süresini, jeneratördeyken faz-nötr gerilimlerini ve büyük motorların dönüş yönünü not et."
],
ozet: [
  "Jeneratörün kVA'sını alternatör, kW'ını (kVA × 0,8) dizel motor sınırlar.",
  "Yükün hem toplam kW'ı hem toplam kVA'sı ayrı ayrı kontrol edilir, üstüne kalkış payı eklenir.",
  "ATS bir enversördür; iki kaynak asla aynı anda bağlanmaz, geri besleme de engellenir.",
  "Her kaynakta N-PE bağı varsa nötr de anahtarlanır; yoksa kaçak akım röleleri atar.",
  "Devreye almada faz sırası, küçük kısa devre akımında koruma ve yüklü test kontrol edilir."
],
modul: [20, 9, 39]
};
